// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"airdrop":{"slug":"airdrop","cat":"basics","en":"Airdrop","contentLocale":"zh-Hans","term":"空投（Airdrop）","aka":["Airdrop","撸空投","撸毛"],"short":"空投是项目方免费向符合条件的钱包地址或用户发放代币的方式，常用于奖励早期用户、分散持币和推广项目。","body":[["常见的空投有几类：按历史链上行为发放的回溯空投（比如你曾经使用过某协议）；完成任务后领取的活动空投；以及",["交易所","centralized-exchange"],"面向持币用户发放的空投。中文圈把为拿空投而刻意交互叫“撸毛”。"],["空投是诈骗的高发区。你的钱包里突然出现一个陌生代币，上面写着“访问某网站领取奖励”，这往往是钓鱼：点进去连接钱包、签名授权后，资产就被转走。正规空投一般可以在项目官方渠道核实，不需要你提供",["助记词","seed-phrase"],"或先转账。"],"空投代币上线后经常面临集中抛售，价格波动很大。不同地区对空投收入的税务处理也不同。为空投频繁交互要花 Gas，还可能因被判定为“女巫地址”而被排除在外。"],"example":["假设某协议宣布向早期用户空投，你符合条件可领 800 枚代币。领取时付了约 2 ",["USDT","usdt"]," 的 Gas。代币上线首日价格 0.5 USDT，价值约 400 USDT；如果你拿着不卖，一周后价格跌到 0.2 USDT，就只剩 160 USDT。反过来，为了“刷”这个空投，你此前可能已经花了 50 USDT 的 Gas 在各种交互上。"],"mistakes":["点击钱包里陌生代币附带的网址，连接钱包后被钓鱼授权。","为了领空投把助记词输入到所谓的“领取页面”。","以为空投都是免费的钱，忽视了 Gas 成本和代币上线后的价格波动。"],"faq":[{"q":"钱包里突然多了代币是空投吗？","a":"可能是，但更常见的是钓鱼代币。不要去它提示的网站，也不要尝试兑换或转出，先在项目官方渠道核实。"},{"q":"什么是撸毛？","a":"撸毛是中文币圈对“刻意交互以争取空投”的俗称，比如提前使用新协议、跨链、参与测试网等。"}],"title":"什么是空投（Airdrop）？含义与防骗要点","description":"加密货币空投是什么？讲清空投的几种形式、撸毛是什么意思、如何识别钓鱼空投，以及领取空投时的 Gas 成本和价格波动。","related":[["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["token-approval","代币授权（Token Approval）","代币授权是你在链上允许某个智能合约动用你钱包里指定代币的操作，授权额度决定合约最多能转走多少，常用于 DEX 交易和 DeFi 存款。"],["governance-token","治理代币（Governance Token）","治理代币是赋予持有人对协议或 DAO 提案投票权的代币，例如 UNI、AAVE，持有越多投票权越大，但不一定代表能分享协议收入。"],["launchpool","Launchpool（质押挖新币）","Launchpool是交易所推出的新币挖矿活动：你在活动期间把指定代币或稳定币锁定到资金池中，按你在池子里所占的份额每天领取即将上线的新代币。"],["rug-pull","跑路（Rug Pull）","Rug Pull（跑路、拉地毯）是指项目方在吸引投资者买入后，突然撤走流动性池中的资金、大量抛售手中代币或卷走资金，导致代币价格瞬间归零。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"别人说能帮你赚钱，先看他要什么"},"coin":null,"tool":null,"cta":false},"centralized-exchange":{"slug":"centralized-exchange","cat":"trading","en":"Centralized exchange (CEX)","contentLocale":"zh-Hans","term":"中心化交易所（CEX）","aka":["CEX","交易所","Centralized exchange"],"short":"中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。","body":[["在 CEX 上，你把资金存入平台账户后，币由交易所托管，你看到的余额是平台内部的记账。平台用",["订单簿","order-book"],"撮合买卖，提供现货、合约、理财、",["C2C","p2p-trading"]," 等功能，操作体验接近传统券商。多数 CEX 要求完成 ",["KYC","kyc"]," 实名认证。"],["CEX 的优点是",["流动性","liquidity"],"好、下单快、法币",["出入金","fiat-on-ramp"],"方便、出问题时有客服；缺点是你不直接掌握",["私钥","private-key"],"，要承担平台被盗、挪用或倒闭的风险。部分交易所会公布储备金证明（Proof of Reserves），用来展示用户资产有对应的储备。"],"不同 CEX 在手续费（挂单/吃单费率）、上币数量、合约规则、可服务地区和合规牌照上差别很大。选平台时要看清它是否在你所在地合法提供服务，以及充提币支持哪些网络。"],"example":"假设你在某 CEX 买入价值 5,000 USDT 的 BTC，吃单费率 0.1%，手续费 5 USDT；如果改用限价挂单成交，挂单费率 0.08%，手续费 4 USDT。之后你把 BTC 提到自己的钱包，交易所收取一笔固定提币费。若一年内你在这家交易所累计交易 50 万 USDT，0.02 个百分点的费率差就是 100 USDT。","mistakes":["把全部资产长期放在一家交易所，没有分散平台风险。","在不支持你所在地区的平台开户，之后遇到账户限制。","相信冒充交易所客服的私信，泄露验证码或资金密码。"],"faq":[{"q":"CEX 和 DEX 有什么区别？","a":"CEX 由公司托管资产并撮合交易，需要实名；DEX 通过智能合约交易，资产留在你自己的钱包里，一般无需注册，但要自己承担操作和合约风险。"},{"q":"放在交易所的币安全吗？","a":"取决于平台的安全能力和财务状况。可以开启双重验证、设置提币白名单，并关注平台的储备金证明，长期大额持有可考虑转入自托管钱包。"}],"title":"什么是中心化交易所（CEX）？含义与优缺点","description":"中心化交易所（CEX）是什么？讲清交易所托管资产与撮合交易的方式、和 DEX 的区别、手续费差异，以及资产放交易所的风险。","related":[["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"],["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["proof-of-reserves","储备金证明（Proof of Reserves）","储备金证明（PoR）是交易所公开证明自己持有的用户资产储备至少等于用户存款总额的做法，通常结合默克尔树和链上地址来让用户自行核验。"],["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。"],["maker-taker-fees","挂单费与吃单费（Maker/Taker Fee）","挂单费与吃单费是交易所按订单角色收取的两档手续费：挂在订单簿上等待成交、提供流动性的一方付挂单费，立即与已有挂单成交的一方付吃单费。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":"/exchanges","cta":true},"support-and-resistance":{"slug":"support-and-resistance","cat":"trading","en":"Support and resistance","contentLocale":"zh-Hans","term":"支撑位与阻力位（Support and Resistance）","aka":["支撑位","阻力位","压力位","支撑阻力"],"short":"支撑位是价格下跌时多次止跌反弹的价格区域，阻力位（也叫压力位）是价格上涨时多次受阻回落的区域，交易者用它们规划入场、止损和止盈。","body":["支撑和阻力形成的原因是大量订单和心理预期集中在某些价位。比如很多人在某个价格买入过，价格回到那里时，有人会补仓，也有人会解套卖出。整数关口、前期高点低点、长期横盘区间的上下沿，都是常见的支撑阻力区域。",["支撑阻力更应该看作“区域”而不是精确到个位数的一条线。被多次测试、伴随较大",["成交量","trading-volume"],"的区域更有参考意义。一旦有效跌破支撑，它常常会变成新的阻力；突破阻力后，原阻力也可能变成支撑。"],["实操中，交易者常把止损放在支撑区域下方一段距离，而不是正好放在整数位上，因为大量",["止损单","stop-loss"],"堆在同一价位，容易被一根影线集中扫掉。"]],"example":["假设过去两个月 ",["BTC","bitcoin"]," 有三次跌到 58,000 ",["USDT","usdt"]," 附近就反弹，有四次涨到 62,000 附近就回落。你在 58,500 买入，把止损设在 57,400，而不是正好 58,000，给价格留出插针空间。每个 BTC 的计划亏损是 1,100 USDT；如果目标是阻力下方的 61,800，计划盈利是 3,300 USDT，",["盈亏比","risk-reward-ratio"],"为 1:3。"],"mistakes":["把支撑阻力当成精确价格，止损设得过近，被正常波动扫掉。","认为支撑一定会守住，跌破后不止损反而加仓。","在很小的时间周期上画出大量线条，结果每个价格都像支撑或阻力。"],"faq":[{"q":"支撑位跌破之后会怎样？","a":"有效跌破后，原支撑区域经常会转变成阻力，价格反弹到那里时可能再次受阻。是否“有效”通常要看收盘价和成交量，而不是一根影线。"},{"q":"支撑位和阻力位怎么找？","a":"常见方法是找前期多次止跌或受阻的价格区域、整数关口、长期横盘区间的上下沿，周期越大、测试次数越多的区域越重要。"}],"title":"什么是支撑位和阻力位？加密交易怎么画","description":"解释支撑位和阻力位（压力位）的形成原因、如何在K线图上找出它们，以及怎样用支撑阻力规划止损和止盈位置。","related":[["candlestick-chart","K线图（Candlestick Chart）","K线图是用一根根K线记录每个时间段开盘价、最高价、最低价和收盘价的价格图表，是加密货币交易软件中最常用的看盘方式。"],["stop-loss","止损单（Stop-Loss）","止损单是预先设定一个触发价，当价格不利地达到该价位时自动卖出（或平仓）以限制亏损的订单。"],["limit-order","限价单（Limit Order）","限价单是指定价格买入或卖出的订单，只在市场价格达到或优于你设定的价格时才成交，可能部分成交或一直不成交。"],["all-time-high","历史最高价（ATH）","历史最高价（ATH，All-Time High）是某个资产自上市交易以来曾达到的最高价格，创新高即价格突破这一纪录。"]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"一根K线，到底告诉你哪四件事？"},"coin":null,"tool":null,"cta":false},"dollar-cost-averaging":{"slug":"dollar-cost-averaging","cat":"trading","en":"Dollar-cost averaging (DCA)","contentLocale":"zh-Hans","term":"定投（DCA）","aka":["定期定额","美元成本平均法","DCA"],"short":"定投（DCA）是按固定周期、用固定金额买入同一资产的策略，不去猜测高低点，借助分批买入摊平成本、降低一次性买在高位的风险。","body":[["定投的核心是纪律：比如每周一买入 500 ",["USDT","usdt"]," 的 ",["BTC","bitcoin"],"，不管当时涨还是跌。价格低时同样的钱买到更多币，价格高时买到更少，长期下来平均持仓成本通常低于同期价格的简单平均值。"],["定投并不能保证盈利。如果一个资产长期下跌，定投只会让你在下跌中持续加仓；它适合你本来就打算",["长期持有","hodl"],"、并且能接受较大波动的资产。定投节奏也要和现金流匹配，最好用不影响生活的闲钱。"],["很多",["交易所","centralized-exchange"],"提供“定投”或“自动投资”功能，到点自动从你的余额扣款买入，有的还支持按日、按周或按月设置。使用前留意每笔买入的手续费、使用的是市价还是限价，以及余额不足时会不会跳过。"]],"example":["假设你每周用 500 USDT 买 ",["ETH","ethereum"],"，连续四周的价格分别是 2,500、2,000、2,500、2,000 USDT。四次分别买到 0.2、0.25、0.2、0.25 个 ETH，共 0.9 个 ETH，总投入 2,000 USDT，平均成本约 2,222 USDT。而这四个价格的简单平均是 2,250 USDT，定投成本更低，因为便宜时买得多。"],"mistakes":["把定投当作稳赚策略，对长期下跌、基本面变差的币也无限期定投。","价格一跌就停掉定投，价格一涨又加大金额，失去了定投的纪律性。","忽略每笔小额买入的手续费，频率过高导致成本占比偏大。"],"faq":[{"q":"定投比特币多久一次比较好？","a":"常见做法是每周或每月一次，关键是频率固定、金额能长期坚持。频率过高会增加手续费占比，频率过低则平摊效果变弱。"},{"q":"定投一定能赚钱吗？","a":"不一定。定投只能降低买点选择不当的风险，最终结果取决于资产本身的长期表现和你卖出的时机。"}],"title":"什么是定投（DCA）？加密货币定投怎么做","description":"解释加密货币定投（DCA）的原理、如何摊低平均成本、适合哪些资产，以及使用交易所自动定投功能时要注意的细节。","related":[["hodl","HODL（长期持有）","HODL 是币圈对“长期持有不卖出”的俗称，源自 2013 年论坛里把 hold 拼错的帖子，后来也被解释为 Hold On for Dear Life。"],["volatility","波动率（Volatility）","波动率是衡量资产价格在一段时间内上下变动幅度的指标，波动率越高，价格涨跌越剧烈，加密货币通常远高于股票和外汇。"],["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。"],["grid-trading-bot","网格交易机器人（Grid trading bot）","网格交易机器人是在你设定的价格区间内按等距价位自动挂出一组买单和卖单的交易工具，价格每下跌一格就买入、每上涨一格就卖出，赚取震荡中的差价。"],["spot-trading","现货交易（Spot Trading）","现货交易是以当前市场价格直接买卖加密货币并即时完成交割的交易方式，买入后你真正持有这个币。"]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"先想能亏多少，再决定买多少"},"coin":null,"tool":null,"cta":true},"usdt-margined-futures":{"slug":"usdt-margined-futures","cat":"derivatives","en":"USDT-margined (linear) futures","contentLocale":"zh-Hans","term":"U本位合约（USDT-Margined Futures）","aka":["U本位","USDT 本位合约","正向合约","linear futures"],"short":"U本位合约是以 USDT 等稳定币作为保证金并结算盈亏的合约，也叫正向或线性合约，盈亏直接以 USDT 计算，是新手最常用的合约类型。","body":[["在 U 本位合约里，你存入 ",["USDT","usdt"],"，开仓数量以币为单位（比如 0.5 ",["BTC","bitcoin"]," 或 2 ",["ETH","ethereum"],"），盈亏 = 数量 × 价格变化，是线性的：价格每涨 100 USDT，1 个币的多单就赚 100 USDT。计算方式直观，几乎所有",["交易对","trading-pair"],"都用同一种 USDT 余额作保证金。"],["因为保证金是",["稳定币","stablecoin"],"，开多时保证金本身不会随币价下跌而贬值，这一点和",["币本位","coin-margined-futures"],"不同。一个 USDT 账户还可以同时交易 BTC、ETH、SOL 等多个币的合约，在全仓模式下共享保证金。部分交易所也提供 USDC 本位合约，逻辑相同。"],"需要注意，U 本位合约的价值以 USDT 计算，USDT 本身有发行方和锚定风险，虽然大多数时候与美元接近 1:1，但并不是银行存款。"],"example":"假设 ETH 价格 3,000 USDT，你在 U 本位合约开多 2 ETH，合约价值 6,000 USDT，5 倍杠杆占用 1,200 USDT 保证金。价格涨到 3,300，盈利 2 × 300 = 600 USDT，相当于保证金的 50%。价格跌到 2,850，亏损 2 × 150 = 300 USDT，保证金剩 900 USDT。盈亏完全按价格变化线性计算。","mistakes":["以为 U 本位合约没有风险，因为保证金是稳定币，忽视杠杆强平。","全仓模式下多个币种合约共享保证金，一个仓位大亏拖累所有仓位。","把开仓数量和保证金金额混淆，下单时填错单位。"],"faq":[{"q":"新手应该选 U 本位还是币本位？","a":"多数新手选择 U 本位，因为盈亏以 USDT 直接显示，计算简单，保证金不会随币价波动。持有大量币想以币计算收益的人才更常用币本位。"},{"q":"U本位合约的盈亏怎么算？","a":"盈亏等于持仓数量乘以价格变化。例如多单 0.5 BTC，价格上涨 1,000 USDT，盈利 500 USDT。"}],"title":"U本位合约是什么？USDT 保证金合约入门","description":"解释U本位合约（USDT 保证金线性合约）的计算方式、和币本位合约的区别、全仓共享保证金的影响，以及常见下单误区。","related":[["coin-margined-futures","币本位合约（Coin-Margined Futures）","币本位合约是用 BTC、ETH 等加密货币本身作为保证金并结算盈亏的合约，也叫反向合约，盈亏以币计价，而不是以 USDT 计价。"],["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["usdt","USDT（泰达币）","USDT（泰达币）是由 Tether 公司发行、设计为与美元 1:1 挂钩的稳定币，也是市值和交易量最大的稳定币之一，大多数交易所的现货和合约都以它计价。"],["cross-margin","全仓保证金（Cross Margin）","全仓保证金是一种保证金模式，账户内所有可用余额共同为全部全仓仓位提供保证金，抗波动能力更强，但一旦强平可能亏掉整个账户余额。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"现货和合约，买到的不是同一件事"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"open-interest":{"slug":"open-interest","cat":"derivatives","en":"Open interest","contentLocale":"zh-Hans","term":"持仓量（Open Interest）","aka":["未平仓合约","未平仓量","OI"],"short":"持仓量是某个合约市场中所有尚未平仓的合约总量，每一份多单都对应一份空单，它衡量的是有多少资金仍然留在市场里。","body":[[["成交量","trading-volume"],"统计的是一段时间内成交了多少，持仓量统计的是此刻还有多少仓位没平。新开多和新开空成交时，持仓量增加；多空双方都平仓成交时，持仓量减少；一方平仓、另一方新开仓时，持仓量不变。"],["交易者常把持仓量和价格结合起来看：价格上涨且持仓量上升，说明有新资金入场；价格上涨但持仓量下降，更多是空头平仓推动。持仓量在短时间内快速堆高，又伴随",["资金费率","funding-rate"],"偏离，往往意味着",["杠杆","leverage"],"拥挤，后续可能出现集中",["强平","liquidation"],"。"],["持仓量可以用合约张数、币数量或 ",["USDT","usdt"]," 金额表示，不同",["交易所","centralized-exchange"],"和数据平台口径不同。看全市场持仓量时，要注意是否已经把各交易所的数据统一换算。"]],"example":"假设某个新合约刚上线，甲开多 2 BTC，乙开空 2 BTC，持仓量是 2 BTC。之后甲把多单卖给新入场的丙，丙开多 2 BTC，甲平仓离场，持仓量仍是 2 BTC。最后丙平多、乙平空，两人互为对手成交，持仓量回到 0。全程成交量是 6 BTC，但持仓量最高只有 2 BTC。","mistakes":["把持仓量和成交量混为一谈。","看到持仓量上升就认为是多头在加仓，其实每份多单都有一份空单。","对比不同平台的持仓量时没统一口径，币数量和 USDT 金额混用。"],"faq":[{"q":"持仓量增加是看涨吗？","a":"不一定。持仓量增加只说明新开仓的资金变多，多空双方同时增加，需要结合价格走势和资金费率判断哪一方更主动。"},{"q":"持仓量和成交量有什么区别？","a":"成交量是一段时间内的成交总额，持仓量是某一时刻未平仓合约的存量。成交量大不代表持仓量大。"}],"title":"持仓量是什么？合约未平仓量（OI）怎么看","description":"解释合约持仓量（未平仓合约 OI）的含义、它与成交量的区别、如何结合价格和资金费率解读持仓变化，以及常见误读。","related":[["trading-volume","成交量（Trading Volume）","成交量是在一段时间内实际成交的资产数量或金额，例如 24 小时成交量，用来衡量一个币或一个市场的交易活跃程度。"],["funding-rate","资金费率（Funding Rate）","资金费率是永续合约中多头和空头之间定期互相支付的费率，用来让永续合约价格贴近现货指数价格，正费率时多头付给空头。"],["long-short-ratio","多空比（Long/Short Ratio）","多空比是交易所统计的持有多单用户（或多单持仓）与持有空单用户（或空单持仓）之间的比例，用来观察散户或大户在某个合约上的情绪偏向。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"hot-wallet":{"slug":"hot-wallet","cat":"wallets-security","en":"Hot wallet","contentLocale":"zh-Hans","term":"热钱包（Hot Wallet）","aka":["热钱包","Hot wallet","在线钱包"],"short":"热钱包是私钥存放在联网设备上的加密货币钱包，例如手机钱包和浏览器插件钱包，使用方便，但更容易受到网络攻击。","body":[["“热”指的是联网。手机 App 钱包、浏览器插件钱包、电脑客户端钱包都属于热钱包：",["私钥","private-key"],"保存在一台经常上网的设备里，签名和转账都能随时完成，适合日常交易、参与 ",["DeFi","defi"]," 和领",["空投","airdrop"],"。"],["风险也来自联网：手机中了木马、装了假冒钱包、在",["钓鱼网站","phishing"],"上签了恶意授权，都可能让资产被转走。",["交易所","centralized-exchange"],"也有热钱包，用来处理用户的日常提现，通常只放一小部分资金，大部分放在",["冷钱包","cold-wallet"],"里。"],"比较稳妥的做法是分层管理：热钱包只放近期要用的小额资金，长期持有的大额资产放到冷钱包或硬件钱包中。"],"example":"比如你总共有价值 10,000 USDT 的加密资产，可以把 500 USDT 放在手机热钱包里用来交互链上应用，剩下 9,500 USDT 放在硬件钱包。即使某天误点钓鱼链接导致热钱包被盗，最大损失也被限制在 500 USDT，即总资产的 5%。","mistakes":["把全部资产长期放在一个浏览器插件钱包里，还天天连接陌生网站。","从搜索广告或私信链接下载钱包 App，装到了仿冒版本。","用同一个热钱包既存大额资产又频繁签名授权，风险全部叠在一起。"],"faq":[{"q":"热钱包和冷钱包的区别是什么？","a":"区别在于私钥所在的设备是否联网。热钱包的私钥在联网设备上，方便但暴露面大；冷钱包的私钥离线保存，转账麻烦一些但更难被远程盗取。"},{"q":"交易所账户算热钱包吗？","a":"交易所账户是托管账户，私钥在平台手里，不算你的热钱包。不过交易所自身会用热钱包处理提现，用冷钱包存放大部分储备。"}],"title":"什么是热钱包？热钱包的含义、用途和风险","description":"热钱包是什么意思？本文讲清热钱包与冷钱包的区别、适合放多少资金，以及手机和插件钱包最常见的被盗原因与防范方法。","related":[["cold-wallet","冷钱包（冷存储）","冷钱包是把私钥保存在不联网环境中的钱包或存储方式，例如硬件钱包和离线生成的纸钱包，主要用于长期、安全地存放大额加密资产。"],["hardware-wallet","硬件钱包（Hardware Wallet）","硬件钱包是一种专门保管私钥的小型实体设备，私钥在设备内部生成并签名，从不传到电脑或手机上，是最常用的冷钱包形式。"],["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。"],["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"seed-phrase":{"slug":"seed-phrase","cat":"wallets-security","en":"Seed phrase (recovery phrase)","contentLocale":"zh-Hans","term":"助记词（Seed Phrase）","aka":["助记词","恢复短语","Seed phrase","Recovery phrase"],"short":"助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。","body":[["大多数钱包按 BIP-39 标准生成助记词，词表里共有 2048 个单词。助记词经过计算得到种子，再推导出各条链、各个地址的",["私钥","private-key"],"。所以一组助记词往往对应你在多条链上的所有地址，换手机或换钱包软件时，输入它就能完整恢复。"],["助记词就是钱包的“总钥匙”。正规钱包、",["交易所","centralized-exchange"],"和客服在任何情况下都不会向你索要助记词，任何要求你输入助记词来“验证”“解冻”“领",["空投","airdrop"],"”的网站或个人，都应视为诈骗。"],"保管上建议手写在纸上或刻在金属板上，存放在不同的安全地点，不要拍照、截图、复制到剪贴板或上传云端。"],"example":["一组 12 个单词的助记词，可能组合数约为 2048 的 12 次方，约等于 5.4 乘以 10 的 39 次方，靠猜几乎不可能。假设你的钱包里有 ",["ETH","ethereum"],"、BNB 链和 Polygon 上共 3 个地址，总值 6,000 ",["USDT","usdt"],"，它们都由同一组助记词控制；一旦这 12 个单词被别人看到，3 个地址里的资产会被同时转走。"],"mistakes":["把助记词截图存在相册里，相册同步到云端后被盗。","在收到“钱包需要升级验证”的消息后，把助记词输入到陌生网页。","只抄了单词没记顺序，或抄错一个词也不核对，恢复时才发现无法使用。"],"faq":[{"q":"助记词和私钥是一回事吗？","a":"不完全一样。私钥对应单个地址，助记词是更上层的备份，可以推导出一个钱包里多个地址的私钥。"},{"q":"助记词丢了还能找回吗？","a":"如果钱包还能正常打开，应立即重新抄写或把资产转到新钱包。如果钱包和助记词都丢了，没有任何人能帮你恢复。"},{"q":"交易所账户有助记词吗？","a":"普通交易所账户没有，登录靠账号密码和 2FA，私钥由平台保管。只有自托管钱包才有你自己的助记词。"}],"title":"什么是助记词？含义、作用与安全保管方法","description":"助记词是什么意思？了解 12 或 24 个单词如何控制整个钱包、与私钥的关系，以及助记词正确的备份方式和最常见的诈骗套路。","related":[["private-key","私钥（Private Key）","私钥是一串只有持有人知道的随机数字，用来对交易进行数字签名，证明你有权动用某个地址里的资产，私钥泄露就等于资产失控。"],["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。"],["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["hardware-wallet","硬件钱包（Hardware Wallet）","硬件钱包是一种专门保管私钥的小型实体设备，私钥在设备内部生成并签名，从不传到电脑或手机上，是最常用的冷钱包形式。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"别人说能帮你赚钱，先看他要什么"},"coin":null,"tool":null,"cta":false},"public-key":{"slug":"public-key","cat":"wallets-security","en":"Public key","contentLocale":"zh-Hans","term":"公钥（Public Key）","aka":["公钥","Public key"],"short":"公钥是由私钥通过数学运算得出、可以公开的密钥，网络用它来验证交易签名是否由对应私钥签出，钱包地址也是由公钥进一步计算得来的。","body":[["公钥和",["私钥","private-key"],"是一对。",["比特币","bitcoin"],"、",["以太坊","ethereum"],"使用椭圆曲线加密，从私钥算出公钥很容易，但从公钥倒推私钥在现有计算能力下不可行，所以公钥可以放心公开。"],["日常转账时你很少直接看到公钥。钱包会把公钥经过哈希等处理变成更短的",["钱包地址","wallet-address"],"，你把地址发给别人收款即可。交易发出后，签名和公钥会被链上",["节点","node"],"用来核验交易确实出自地址的所有者。"],["理解公钥的意义在于分清哪些可以公开：地址和公钥可以公开，私钥和",["助记词","seed-phrase"],"绝对不能。有人以“需要你的公钥验证”为名索要助记词，就是典型的偷换概念。"]],"example":"可以把它类比成邮箱：公钥像是带锁的信箱的位置和锁的样式，谁都能看到；私钥是唯一能开锁的钥匙。以太坊地址就是对公钥做 Keccak-256 哈希后取最后 20 字节，即 40 个十六进制字符再加 0x 前缀，总共 42 个字符。你把这 42 个字符公开出去收款，不会影响资产安全。","mistakes":["把公钥、地址和私钥混为一谈，对方要“密钥”时把私钥发了出去。","以为公开地址会导致资产被盗，其实风险来自私钥和助记词泄露。"],"faq":[{"q":"公钥和钱包地址一样吗？","a":"不一样。地址是公钥经过哈希和编码后得到的较短形式，日常收款用地址即可，两者都可以公开。"},{"q":"别人知道我的公钥会怎样？","a":"对方无法用公钥转走你的资产，只能验证签名或查看与之相关的链上记录。需要注意的是链上记录公开，地址的交易历史任何人都能查到。"}],"title":"什么是公钥？公钥、私钥和地址的关系","description":"公钥是什么意思？用通俗的方式讲清公钥如何由私钥生成、怎样验证交易签名、与钱包地址的区别，以及哪些信息可以安全公开。","related":[["private-key","私钥（Private Key）","私钥是一串只有持有人知道的随机数字，用来对交易进行数字签名，证明你有权动用某个地址里的资产，私钥泄露就等于资产失控。"],["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["blockchain","区块链（Blockchain）","区块链是一种由众多节点共同维护、按时间顺序把交易打包成区块并用密码学串联起来的公开账本，写入后极难篡改。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"transaction-hash":{"slug":"transaction-hash","cat":"wallets-security","en":"Transaction hash (TxID)","contentLocale":"zh-Hans","term":"交易哈希（TxID）","aka":["TxID","TxHash","交易 ID","哈希值"],"short":"交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。","body":[["每笔",["区块链","blockchain"],"交易被广播后都会生成一个哈希值，",["以太坊","ethereum"],"等 EVM 链上是以 0x 开头的 66 个字符，",["比特币","bitcoin"],"上是 64 个十六进制字符。它就像快递单号，任何人拿着它都能在对应链的",["区块浏览器","block-explorer"],"中查询。"],["提币后，",["交易所","centralized-exchange"],"的提现记录里通常会显示 TxID。如果对方说“没收到”，先把 TxID 放进浏览器查：显示待处理，说明还在排队；显示成功并有足够",["确认数","block-confirmations"],"，说明链上已经到达，问题出在接收方入账环节。"],"联系交易所客服处理未到账问题时，交易哈希几乎是必填信息。注意要在正确的链上查询，同一个哈希放到别的链的浏览器里会显示查不到。"],"example":"假设你从交易所提了 0.05 BTC，提现记录显示状态为“已完成”，并给出一串 64 位 TxID。你把它粘贴到比特币区块浏览器，看到交易已被打包，确认数为 1，而接收方交易所要求 2 个确认才入账。按比特币平均约 10 分钟出一个块估算，再等十几分钟左右通常就会到账，不必急着提交工单。","mistakes":["提现显示“已完成”就以为对方一定入账，没去链上核实确认数。","在错误的区块浏览器里查询，看到“未找到”就以为币丢了。","联系客服时只说“没到账”，不提供交易哈希，导致处理变慢。"],"faq":[{"q":"在哪里找交易哈希？","a":"交易所的提现或充值记录、钱包 App 的交易详情页里一般都有 TxID，点击通常可以直接跳转到区块浏览器。"},{"q":"交易所内部转账为什么没有交易哈希？","a":"同一交易所用户之间的转账往往在平台账本里直接完成，不上链，所以没有链上哈希，只有平台内部的流水号。"}],"title":"什么是交易哈希（TxID）？如何查询转账状态","description":"交易哈希 TxID 是什么？了解它在哪里查看、如何用区块浏览器追踪转账是否到账，以及提币未到账时联系客服需要准备的信息。","related":[["block-explorer","区块浏览器（Block explorer）","区块浏览器是一种可以按交易哈希、钱包地址或区块高度查询区块链上公开记录的网站或工具，例如以太坊的Etherscan和波场的Tronscan。"],["block-confirmations","区块确认数（Confirmations）","区块确认数是指一笔交易被打包进区块后，其后又新增了多少个区块，确认数越多，交易被回滚的可能性越小，交易所据此决定何时为你入账。"],["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。"],["mempool","内存池（Mempool）","内存池是区块链节点用来暂存已广播但尚未被打包进区块的交易的等待区，交易在这里排队，矿工或验证者通常优先打包手续费更高的交易。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"显示成功却没到账，该查哪里？"},"coin":null,"tool":null,"cta":false},"address-poisoning":{"slug":"address-poisoning","cat":"wallets-security","en":"Address poisoning","contentLocale":"zh-Hans","term":"地址投毒（Address Poisoning）","aka":["地址投毒","地址污染","零转账诈骗","Address poisoning"],"short":"地址投毒是一种诈骗手法，骗子生成一个首尾字符与你常用地址相同的假地址，向你发送小额或零额转账，让它混进你的交易记录，等你复制错地址。","body":[["很多人转账时习惯从钱包或",["区块浏览器","block-explorer"],"的历史记录里复制地址，并且只看开头和结尾几位。骗子正是利用这一点：用工具批量生成首尾 4 到 6 位相同的“靓号”，然后向你发一笔 0 金额或极小金额的代币，让假地址出现在你的记录里。"],"下次你要给自己或朋友转账时，如果从记录里复制了这个假地址，资产就会直接进入骗子口袋。由于链上交易不可撤回，这类损失几乎无法挽回。",["防范方法：不要从交易历史复制地址；使用地址簿或",["交易所","centralized-exchange"],["提币白名单","withdrawal-whitelist"],"；核对完整地址或至少比对中间若干位；对不明来源的小额转入保持警惕，不要与其互动。"]],"example":["假设你常用的地址是 0x8F3c……A92e，某天钱包里出现一笔来自 0x8F3c……A92e 的 0.01 ",["USDT","usdt"]," 转入，首尾完全一样，中间却完全不同。一周后你要转 8,000 USDT，从历史记录里复制了最近那条地址，只核对了首尾 4 位就提交了，结果 8,000 USDT 进了骗子的地址。"],"mistakes":["从交易历史或区块浏览器里复制收款地址。","只核对地址的前 4 位和后 4 位。","看到陌生的零额或小额转入不当回事，后续仍在记录里随意复制。"],"faq":[{"q":"收到陌生的小额转账要怎么办？","a":"不要点击、不要回转，也不要从这条记录里复制地址。它本身通常不会动你的资产，危险在于你之后用错地址。"},{"q":"地址投毒能被交易所拦截吗？","a":"部分钱包和交易所会标记可疑的相似地址，但不能完全依赖。使用地址簿、白名单并完整核对地址才是最可靠的方式。"}],"title":"什么是地址投毒？相似地址诈骗如何防范","description":"地址投毒是什么意思？了解骗子如何用首尾相同的假地址混进你的转账记录，以及用地址簿、白名单和完整核对来避免转错的方法。","related":[["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["withdrawal-whitelist","提币白名单（Withdrawal Whitelist）","提币白名单是交易所的一项安全设置，开启后账户只能向你事先登记并验证过的地址提币，即使账户被盗，对方也难以把资产转到陌生地址。"],["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["transaction-hash","交易哈希（TxID）","交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"token-approval":{"slug":"token-approval","cat":"wallets-security","en":"Token approval (allowance)","contentLocale":"zh-Hans","term":"代币授权（Token Approval）","aka":["授权","Approve","额度授权","Allowance"],"short":"代币授权是你在链上允许某个智能合约动用你钱包里指定代币的操作，授权额度决定合约最多能转走多少，常用于 DEX 交易和 DeFi 存款。","body":[["在",["以太坊","ethereum"],"等 EVM 链上，你第一次用 ",["DEX","dex"]," 卖出某个 ERC20 代币时，钱包会先弹出“授权”请求，同意后合约才能从你的地址划转这个代币。授权和实际交易是两笔不同的交易，也都要付 ",["Gas 费","gas-fee"],"。"],"很多应用默认请求“无限授权”，好处是以后不用重复授权，坏处是如果这个合约被黑，或者你授权的其实是钓鱼合约，对方可以在任何时候把你钱包里该代币全部转走，无需你再次确认。","建议只授权本次需要的额度，定期在钱包设置或授权检查工具中查看并撤销不用的授权。撤销本身也是一笔链上交易，需要支付少量 Gas 费。"],"example":["假设你钱包里有 5,000 ",["USDC","usdc"],"，为了在某 DEX 换 100 USDC 的代币，你点了默认的无限授权。半年后这个 DEX 的旧合约被攻击，攻击者利用你的授权一次性转走全部 5,000 USDC。如果当初只授权 100 USDC，最多损失的就是这 100 USDC 中尚未使用的部分。"],"mistakes":["对任何弹窗都直接点确认，不看授权的合约地址和额度。","在空投或领奖页面签了授权，把代币权限交给了陌生合约。","以为把应用网页关掉就等于取消授权，实际上授权一直留在链上。"],"faq":[{"q":"怎么撤销代币授权？","a":"可以在部分钱包的授权管理页面，或使用区块浏览器和第三方授权检查工具，选中对应授权并发起撤销交易。"},{"q":"签名和授权有什么区别？","a":"授权是一笔改变链上额度的交易；有些签名（如 Permit 类签名）不上链也能给出转账权限，同样危险，签之前都要看清内容。"}],"title":"什么是代币授权？无限授权的风险与撤销方法","description":"代币授权（Approve）是什么意思？了解授权额度如何让合约动用你的代币、无限授权为什么危险，以及如何检查并撤销旧授权。","related":[["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"],["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。"],["dex","去中心化交易所（DEX）","去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。"]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"别人说能帮你赚钱，先看他要什么"},"coin":null,"tool":null,"cta":false},"dex":{"slug":"dex","cat":"defi","en":"Decentralized exchange (DEX)","contentLocale":"zh-Hans","term":"去中心化交易所（DEX）","aka":["DEX","去中心化交易所","Decentralized exchange"],"short":"去中心化交易所（DEX）是基于智能合约运行的交易平台，你直接用自己的钱包交易，不需要注册账户或把资产托管给平台，典型代表有 Uniswap 和 PancakeSwap。","body":[["DEX 主要有两种模式：一是",["自动做市商（AMM）","amm"],"，用",["流动性池","liquidity-pool"],"和公式定价，例如 Uniswap；二是链上",["订单簿","order-book"],"，类似",["中心化交易所","centralized-exchange"],"的挂单和吃单，Hyperliquid 等",["永续合约 DEX","perp-dex"]," 多采用这种方式。"],["与中心化交易所（CEX）相比，DEX 通常无需 ",["KYC","kyc"],"，资产始终在你的钱包里，可以交易刚上线的新代币。但你需要自己支付 Gas 费，面对滑点、MEV 夹子攻击、假币和跑路项目，也没有客服帮你处理失误。"],"很多钱包和交易所 App 内置了 DEX 聚合器，会在多个 DEX 之间寻找更优路径，但最终成交价、手续费和滑点仍要在确认前自己核对。"],"example":"假设你在某 DEX 上用 1 ETH 兑换 USDC，界面报价约 3,000 USDC（已扣除 0.3% 的池子手续费，约 9 USDC），滑点容忍设置为 0.5%。这意味着如果价格在打包前变动，你最少能收到 3,000 乘以 99.5%，即约 2,985 USDC，低于这个数交易会自动失败，同时你还要另外支付链上 Gas 费。","mistakes":["根据代币名称搜索买入，没有核对合约地址，结果买到假币。","把滑点容忍度调得很高，给了夹子机器人可乘之机。","忽略 Gas 费，小额交易的总成本反而比在中心化交易所更高。"],"faq":[{"q":"DEX 和 CEX 哪个更安全？","a":"风险类型不同。DEX 没有平台跑路风险，但有合约漏洞、钓鱼授权和操作失误的风险；CEX 操作简单，但资产由平台托管。"},{"q":"在 DEX 交易需要 KYC 吗？","a":"大部分 DEX 协议本身不要求 KYC，只需连接钱包。不过有些前端网站会因地区规定限制访问，各地合规要求也不同。"}],"title":"什么是 DEX？去中心化交易所的原理与风险","description":"DEX 去中心化交易所是什么？了解 AMM 与链上订单簿两种模式、DEX 和 CEX 的区别，以及在 DEX 交易时如何防范假币、滑点和 MEV。","related":[["amm","自动做市商（AMM）","自动做市商（AMM）是一种用流动性池和数学公式自动给代币定价的交易机制，不需要买卖双方挂单撮合，是 Uniswap 等去中心化交易所的核心。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"],["liquidity-pool","流动性池（Liquidity Pool）","流动性池是锁在智能合约里的一对或多种代币储备，交易者直接与池子兑换，存入资金的流动性提供者按份额获得手续费收入，是 DEX 运作的基础。"],["slippage","滑点（Slippage）","滑点是指订单实际成交价格与下单时预期价格之间的差异，常发生在市价单、大额交易、流动性差或行情剧烈波动时。"],["perp-dex","永续合约 DEX（Perp DEX）","永续合约 DEX（Perp DEX）是在链上提供永续合约交易的去中心化平台，你用自己的钱包存入保证金开多或开空，资金费率、强平等机制与中心化交易所类似。"]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":"/compare","cta":false},"flash-loan":{"slug":"flash-loan","cat":"defi","en":"Flash loan","contentLocale":"zh-Hans","term":"闪电贷（Flash Loan）","aka":["闪电贷","Flash loan","闪电借贷"],"short":"闪电贷是一种无需抵押的链上借款，借款和还款必须在同一笔交易内完成，如果交易结束时没有连本带息还清，整笔交易就会被撤销，就像没发生过一样。","body":[[["区块链","blockchain"],"交易具有原子性：一笔交易里的所有步骤要么全部成功，要么全部失败。闪电贷利用这一点，让你在一笔交易里先借出大量资金，执行一系列操作，最后归还本金和手续费；只要最后一步还不上，前面所有操作都会回滚，出借方没有损失。"],["正当用途包括",["套利","arbitrage"],"、为自己的借贷仓位换抵押品、自我清算以减少罚金等。它需要编写",["智能合约","smart-contract"],"或使用专门工具，普通用户很少直接使用。"],["闪电贷也常被用在攻击中：攻击者借来巨额资金，操纵某个",["流动性","liquidity"],"较浅的价格源或利用合约漏洞，一笔交易内完成获利并还款。根源是协议本身的设计缺陷，而不是闪电贷。"]],"example":["假设某代币在 ",["DEX","dex"]," A 上价格为 1.00 ",["USDC","usdc"],"，在 DEX B 上为 1.02 USDC。你在一笔交易里闪电贷借出 100,000 USDC，在 A 买入 100,000 枚，在 B 卖出得到 102,000 USDC，再归还本金加 0.05% 手续费，共 100,050 USDC，剩余 1,950 USDC，扣除 Gas 费后为利润。如果中途价格变动导致还不上，整笔交易回滚，你只损失 Gas 费。"],"mistakes":["以为闪电贷是“无风险白赚”，忽略了失败也要付 Gas 和激烈的套利竞争。","把协议被攻击归咎于闪电贷，而不去看协议本身的价格源设计。","相信社交媒体上“闪电贷套利机器人”的推广，结果是授权或转账骗局。"],"faq":[{"q":"闪电贷为什么不需要抵押？","a":"因为借款和还款在同一笔交易中完成，还不上整笔交易就会失败回滚，出借方的资金始终不会真正流失。"},{"q":"普通人能用闪电贷赚钱吗？","a":"需要会写或部署合约，还要和专业套利机器人竞争，实际门槛很高。号称一键闪电贷套利的工具大多是骗局。"}],"title":"什么是闪电贷？无抵押借款的原理与用途","description":"闪电贷是什么意思？了解闪电贷如何利用交易原子性实现无抵押借款、套利例子的计算方法，以及它为何常出现在 DeFi 攻击中。","related":[["defi-lending","DeFi 借贷","DeFi 借贷是通过智能合约进行的超额抵押借贷，存款人把资产存入资金池赚利息，借款人先存入抵押品再借出其他资产，抵押不足时会被自动清算。"],["oracle","预言机（Oracle）","预言机是把链下数据（如币价、汇率、体育比分）传送到区块链上供智能合约使用的服务，DeFi 借贷、衍生品和稳定币都依赖它获取价格。"],["mev","MEV（最大可提取价值）","MEV（最大可提取价值）是指区块生产者或搜索者通过调整、插入或排除区块中交易的顺序所能额外获得的利润，三明治攻击（夹子）是最常见的例子。"],["smart-contract","智能合约（Smart Contract）","智能合约是部署在区块链上、满足预设条件就自动执行的程序代码，DeFi、NFT 和链上代币都依靠它运行。"]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"wrapped-token":{"slug":"wrapped-token","cat":"defi","en":"Wrapped token","contentLocale":"zh-Hans","term":"封装代币（Wrapped Token）","aka":["包装代币","Wrapped token","WBTC","WETH"],"short":"封装代币是把一种资产按 1:1 比例在另一条链或另一种标准下表示出来的代币，例如 WBTC 让比特币能在以太坊上使用，WETH 把 ETH 变成 ERC20 格式。","body":[[["比特币","bitcoin"],"本身不能在",["以太坊","ethereum"],"上运行。托管方收到真实 BTC 后，在以太坊上铸造等量的 WBTC，赎回时销毁 WBTC 并归还 BTC。这样 BTC 持有者就能把它用于以太坊上的 ",["DEX","dex"]," 和借贷。"],["WETH 则是另一种情况：ETH 是以太坊的",["原生币","coin-vs-token"],"，不完全符合 ERC20 标准，很多 ",["DeFi","defi"]," 合约需要统一的代币接口，于是用合约把 ETH 1:1 封装成 WETH，随时可以无损换回。"],["封装代币的价值依赖于背后的储备和赎回机制。如果托管方出问题或",["跨链桥","cross-chain-bridge"],"被攻击，封装代币可能与原资产脱锚。不同发行方的同类封装币是不同的代币，不能混为一谈。"]],"example":"假设你有 0.5 BTC，想在以太坊借贷协议中作抵押。你通过支持的渠道把它换成 0.5 WBTC，以 BTC 价格 60,000 美元计算，价值 30,000 美元。之后若你想换回 BTC，需要通过赎回渠道销毁 0.5 WBTC，期间可能产生手续费和以太坊 Gas 费，到手会略少于 0.5 BTC。","mistakes":["以为 WBTC 和 BTC 完全一样，忽略了托管方和合约风险。","把封装代币直接转到只支持原生资产的交易所地址。","看到名字相似的“W”开头代币就买入，没核对合约地址。"],"faq":[{"q":"WETH 和 ETH 有什么区别？","a":"价值上 1:1，WETH 是以太坊上 ERC20 格式的 ETH，方便智能合约处理。你可以在钱包或 DEX 上随时互换，只需支付 Gas 费。"},{"q":"封装代币会脱锚吗？","a":"有可能。如果托管储备不足、赎回暂停或跨链桥被攻击，封装代币的市场价格可能低于原资产。"}],"title":"什么是封装代币？WBTC 和 WETH 的含义","description":"封装代币是什么意思？了解 WBTC、WETH 等 Wrapped Token 如何 1:1 对应原资产、托管和赎回机制，以及脱锚和充错地址的风险。","related":[["cross-chain-bridge","跨链桥（Cross-chain Bridge）","跨链桥是把资产或信息从一条区块链转移到另一条区块链的协议，常见方式是在源链锁定资产、在目标链铸造等量的映射代币。"],["liquid-staking","流动性质押（Liquid Staking）","流动性质押是把代币交给质押协议进行质押，同时获得一个可交易的凭证代币（如 stETH），让你在赚取质押奖励的同时仍能使用这部分资产。"],["coin-vs-token","币和代币的区别（Coin vs Token）","币（Coin）通常指一条区块链自己的原生资产，如 BTC、ETH；代币（Token）则是基于已有区块链的智能合约发行的资产，如以太坊上的 USDT。"],["depeg","脱锚（Depeg）","脱锚是指稳定币或锚定类资产的市场价格明显偏离它承诺跟随的价值，例如本应等于1美元的稳定币跌到0.95美元或涨到1.03美元。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"kyc":{"slug":"kyc","cat":"regulation","en":"KYC (know your customer)","contentLocale":"zh-Hans","term":"KYC（了解你的客户）","aka":["身份认证","实名认证","KYC认证"],"short":"KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。","body":[["在大多数受监管的地区，",["中心化交易所","centralized-exchange"],"必须做KYC，这是",["反洗钱","aml"],"（AML）合规要求的一部分。常见流程分级进行：初级认证提交姓名、证件号和证件照片，再做人脸识别；高级认证可能需要地址证明，甚至资金来源说明。认证等级越高，充提币和法币",["出入金","fiat-on-ramp"],"额度通常越高。"],"KYC的意义在于把账户和真实的人对应起来，以便平台识别诈骗、洗钱和制裁风险。对你来说，完成KYC也意味着账户被盗或纠纷时更容易证明你是账户主人。代价是你的身份资料被平台保存，所以只应在官方网站或官方App里提交，并留意平台的数据保护措施。","各平台、各地区的KYC要求不同：有的国家要求所有用户必须认证才能交易，有的平台允许未认证用户小额使用。具体等级和额度要看你所在地区和平台的说明页面。"],"example":["假设某交易所规定：未认证账户每日提币上限等值1,000 ",["USDT","usdt"],"，完成初级认证后提高到50,000 USDT，完成高级认证后提高到2,000,000 USDT。你账户里有8,000 USDT想提到自己的钱包，在未认证状态下需要分8天才能提完；完成初级认证后，一天之内就能全部提走，还剩42,000 USDT的当日额度。"],"mistakes":["把证件照片和人脸视频发给自称“客服”的私聊人员，而不是在官方App里提交。","用别人的身份信息或借用他人账户做认证，日后无法提现或被冻结。","先大额充值再去做认证，结果认证不通过，资金只能按低额度慢慢提。"],"faq":[{"q":"不做KYC能在交易所交易吗？","a":"取决于平台和所在地区。不少平台对未认证用户限制交易或提币额度，受严格监管的地区通常要求完成认证才能使用。"},{"q":"KYC信息会被泄露吗？","a":"任何保存数据的机构都存在风险，因此要选择安全记录较好的平台，只在官方渠道提交资料，并开启双重验证保护账户。"}],"title":"什么是KYC？交易所身份认证的流程与作用","description":"KYC是什么意思？了解交易所实名认证的常见等级、所需资料、对充提额度的影响，以及提交身份资料时的安全注意事项。","related":[["aml","AML（反洗钱）","AML是“反洗钱”（Anti-Money Laundering）的缩写，指金融机构和交易所为识别、阻止非法资金进入正规体系而建立的一整套监控、审查和报告制度。"],["travel-rule","旅行规则（Travel Rule）","旅行规则是FATF第16条建议对虚拟资产服务商的要求：在转账时收集并传递汇款方和收款方的身份信息，让资金和信息一起“旅行”。"],["no-kyc-exchange","免KYC交易所（No-KYC exchange）","免KYC交易所是指不要求用户提交身份证件即可注册、交易或在一定额度内提币的交易平台，包括部分中心化交易所和链上去中心化交易所（DEX）。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"],["vasp","虚拟资产服务提供商（VASP）","VASP是“虚拟资产服务提供商”的缩写，指为他人提供加密资产兑换、转账、托管或发行相关服务的企业，例如中心化交易所和托管钱包服务商。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC怎么做？证件应该交给谁？"},"coin":null,"tool":null,"cta":false},"demo-trading":{"slug":"demo-trading","cat":"exchange-features","en":"Demo trading","contentLocale":"zh-Hans","term":"模拟交易（Demo trading）","aka":["模拟盘","模拟交易","Demo trading","虚拟盘"],"short":"模拟交易是交易所用虚拟资金提供的练习环境，界面和行情与真实市场一致，你可以在不投入真钱的情况下熟悉下单、杠杆、止损和强平机制。","body":[["多数大型",["交易所","centralized-exchange"],"都提供合约模拟盘，部分也支持现货、跟单或交易机器人的模拟版本。系统会发放一笔虚拟资金，你可以练习开仓、平仓、设置止盈止损，观察",["资金费率","funding-rate"],"和保证金率的变化，还能看到仓位在什么价格会被",["强平","liquidation"],"（爆仓）。"],["模拟交易最大的价值是让你在低成本下弄懂规则：例如10倍",["杠杆","leverage"],"下价格变动多少会亏掉一半保证金，逐仓和全仓的",["强平价","liquidation-price"],"有什么不同，",["限价单","limit-order"],"和市价单的成交差别。"],"它的局限也很明显：虚拟资金不会让你紧张，你在模拟盘里敢扛单、敢加仓，换成真钱时心态完全不同；模拟环境的成交和滑点也可能比真实市场更理想。练好规则之后，可以先用很小的真实资金过渡。"],"example":"假设你在模拟盘用1,000 USDT保证金、10倍杠杆在60,000 USDT做多BTC，名义仓位10,000 USDT，约0.1667 BTC。价格跌到57,000，跌幅5%，仓位亏损500 USDT，等于保证金的50%。再跌几个百分点，就会接近强平价。你在模拟盘上看到这个过程后，决定实盘只用3倍杠杆，并在56,400设止损：同样的保证金下，跌6%时亏损约180 USDT，只占保证金的18%。","mistakes":["在模拟盘用最高杠杆随意下单，养成不设止损的习惯。","模拟盘赚了几次就立刻大额实盘，忽略心态和滑点的差异。","以为模拟盘的虚拟资金可以兑换或提现。"],"faq":[{"q":"模拟交易的收益能提现吗？","a":"不能。模拟盘使用的是虚拟资金，盈亏只用于练习，不能转入真实账户或提现。"},{"q":"模拟盘练多久再实盘比较合适？","a":"没有固定时间。至少要能清楚算出杠杆、保证金和强平价的关系，并能稳定执行止损规则后，再用小资金开始实盘。"}],"title":"什么是模拟交易？合约模拟盘怎么练","description":"模拟交易是什么？了解交易所模拟盘的用途，如何用虚拟资金练习杠杆、止损和强平计算，以及模拟和实盘之间的差距。","related":[["perpetual-futures","永续合约（Perpetual Futures）","永续合约是一种没有到期日的期货合约，可以无限期持有，通过多空双方定期互付资金费率，让合约价格始终贴近现货价格。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"],["copy-trading","跟单交易（Copy trading）","跟单交易是交易所提供的一种功能，让你选择一位公开交易记录的带单员，按设定的比例或金额自动复制他的开仓和平仓操作。"],["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。"]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10倍杠杆，是钱变多，还是风险变大？"},"coin":null,"tool":null,"cta":true}});
